inline FInstancedStruct FSprocket::PartFromTable(const UnrealTest::Part InType, const void* InValue)
{
	switch (InType)
	{
	case UnrealTest::Part::Included_SharedThing:
		return FInstancedStruct::Make<FSharedThing>(FSharedThing::FromTable(*static_cast<const UnrealTest::Included::SharedThing*>(InValue)));
	case UnrealTest::Part::Included_Cog:
		return FInstancedStruct::Make<FCog>(FCog::FromTable(*static_cast<const UnrealTest::Included::Cog*>(InValue)));
	case UnrealTest::Part::Included_Vec2i:
		return FInstancedStruct::Make<FVec2i>(FVec2i::FromNative(*static_cast<const UnrealTest::Included::Vec2i*>(InValue)));
	case UnrealTest::Part::NONE:
	default:
		return FInstancedStruct();
	}
}

inline FInstancedStruct FSprocket::PartFromNative(const UnrealTest::PartUnion& InValue)
{
	switch (InValue.type)
	{
	case UnrealTest::Part::Included_SharedThing:
		return FInstancedStruct::Make<FSharedThing>(FSharedThing::FromNative(*InValue.AsIncluded_SharedThing()));
	case UnrealTest::Part::Included_Cog:
		return FInstancedStruct::Make<FCog>(FCog::FromNative(*InValue.AsIncluded_Cog()));
	case UnrealTest::Part::Included_Vec2i:
		return FInstancedStruct::Make<FVec2i>(FVec2i::FromNative(*InValue.AsIncluded_Vec2i()));
	case UnrealTest::Part::NONE:
	default:
		return FInstancedStruct();
	}
}

inline UnrealTest::PartUnion FSprocket::PartToNative(const FInstancedStruct& InValue)
{
	UnrealTest::PartUnion Native;
	if (const FSharedThing* Elem = InValue.GetPtr<FSharedThing>())
	{
		Native.Set(Elem->ToNative());
		return Native;
	}
	if (const FCog* Elem = InValue.GetPtr<FCog>())
	{
		Native.Set(Elem->ToNative());
		return Native;
	}
	if (const FVec2i* Elem = InValue.GetPtr<FVec2i>())
	{
		Native.Set(Elem->ToNative());
		return Native;
	}
	checkf(!InValue.IsValid(), TEXT("%s is not a member of UnrealTest::Part"), *InValue.GetScriptStruct()->GetName());
	return Native;
}

